+/**
+ * Variance per item between two days (inclusive): theoretical use from the
+ * sales sold in those days against the actual use (every consume movement),
+ * as actual minus theoretical. Only items where either is above zero.
+ */
+export function varianceReport(store, from, to) {
+  const theoretical = new Map();
+  const actual = new Map();
+  for (const s of store.data.sales ?? []) {
+    const day = s.soldAt.slice(0, 10);
+    if (day < from || day > to) continue;
+    const dish = (store.data.dishes ?? []).find((d) => d.id === s.dishId);
+    const recipe = dish && store.data.recipes.find((r) => r.id === dish.recipeId);
+    if (!recipe) continue;
+    for (const n of scaled(recipe, s.qty)) theoretical.set(n.itemId, (theoretical.get(n.itemId) ?? 0) + n.qty);
+  }
+  for (const m of store.data.movements) {
+    if (m.type !== "consume") continue;
+    const day = m.at.slice(0, 10);
+    if (day < from || day > to) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (batch) actual.set(batch.itemId, (actual.get(batch.itemId) ?? 0) + m.qty);
+  }
+  const r3 = (x) => Math.round(x * 1000) / 1000;
+  const ids = new Set([...theoretical.keys(), ...actual.keys()]);
+  return [...ids]
+    .sort((a, b) => a - b)
+    .map((itemId) => {
+      const t = r3(theoretical.get(itemId) ?? 0);
+      const a = r3(actual.get(itemId) ?? 0);
+      return { itemId, theoretical: t, actual: a, difference: r3(a - t) };
+    })
+    .filter((l) => l.theoretical > 0 || l.actual > 0);
+}
