+++ b/src/io/sales-import.js
@@ -0,0 +1,56 @@
+// Importing sales from the till CSV (ticket,soldAt,dishId,qty). Every dish
+// sold uses `qty` portions of its recipe, booked as "consume" movements with
+// the ref `sale:<ticket>`. Tickets already imported are skipped. The whole
+// file is all or nothing: one bad row or a shortage and nothing is imported.
+import { AppError } from "../errors.js";
+import { getDish } from "../domain/menu.js";
+import { consume } from "../domain/batches.js";
+import { getRecipe, scaled } from "../domain/recipes.js";
+import { getItem, onHand } from "../domain/items.js";
+import { parseCsvObjects } from "./csv.js";
+
+const HEADER = ["ticket", "soldAt", "dishId", "qty"];
+const bad = (reason) => new AppError("bad_request", { reason });
+
+/** Imports sales; returns { tickets, dishes } counts or throws bad_request naming the row. */
+export function importSales(store, text) {
+  const rows = parseCsvObjects(text);
+  for (const k of HEADER)
+    if (rows.length && !(k in rows[0])) throw bad(`missing column ${k}`);
+  const clean = rows.map((r, i) => {
+    const where = `row ${i + 2}`;
+    const dishId = Number(r.dishId);
+    const qty = Number(r.qty);
+    const soldMs = Date.parse(r.soldAt);
+    if (!r.ticket) throw bad(`${where}: ticket is required`);
+    if (!/^\d{4}-\d{2}-\d{2}T/.test(r.soldAt) || Number.isNaN(soldMs)) throw bad(`${where}: bad soldAt`);
+    if (!(store.data.dishes ?? []).some((d) => d.id === dishId)) throw bad(`${where}: unknown dish`);
+    if (!Number.isInteger(qty) || qty < 1) throw bad(`${where}: bad qty`);
+    return { row: i + 2, ticket: r.ticket, soldAt: new Date(soldMs).toISOString(), dishId, qty };
+  });
+
+  store.data.sales ??= [];
+  const known = new Set(store.data.sales.map((s) => s.ticket));
+  const fresh = clean.filter((c) => !known.has(c.ticket));
+  const snapshot = structuredClone(store.data);
+  try {
+    for (const c of fresh) {
+      const recipe = getRecipe(store, getDish(store, c.dishId).recipeId);
+      for (const n of scaled(recipe, c.qty)) {
+        const item = getItem(store, n.itemId);
+        const available = onHand(store, n.itemId);
+        if (available < n.qty)
+          throw bad(`row ${c.row}: not enough ${item.name} (only ${available} ${item.unit} left)`);
+        consume(store, n.itemId, n.qty, { at: c.soldAt, ref: `sale:${c.ticket}` });
+      }
+      store.data.sales.push({ ticket: c.ticket, soldAt: c.soldAt, dishId: c.dishId, qty: c.qty });
+    }
+  } catch (e) {
+    store.data = snapshot;
+    throw e;
+  }
+  return {
+    tickets: new Set(fresh.map((c) => c.ticket)).size,
+    dishes: fresh.reduce((s, c) => s + c.qty, 0),
+  };
+}
